// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/utils/Context.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title PrivateLabelContract
 * @author Your Name
 * @notice This contract manages private label transactions between a private limited company and government entities.
 * @dev This contract implements access control, reentrancy protection, and proper error handling.
 */

contract PrivateLabelContract is Context, AccessControl, ReentrancyGuard {
    // Roles
    bytes32 public constant ADMIN = "ADMIN";
    bytes32 public constant COMPANY = "COMPANY";
    bytes32 public constant GOVERNMENT = "GOVERNMENT";

    // Mapping of license IDs to their holders
    mapping(string => address) private licenses;

    // Mapping of addresses to their license IDs
    mapping(address => string[]) private licenseHolders;

    // Event emitted when a new license is created
    event LicenseCreated(string indexed licenseId, address indexed holder);

    // Event emitted when a license is assigned to a government entity
    event LicenseAssigned(string indexed licenseId, address indexed assigner, address indexed assignee);

    // Event emitted when a license is transferred
    event LicenseTransferred(string indexed licenseId, address indexed sender, address indexed receiver);

    // Event emitted when a license is revoked
    event LicenseRevoked(string indexed licenseId, address indexed revoker);

    /**
     * @notice Initializes the contract with the given admin address.
     * @dev Grants the ADMIN role to the initial admin address.
     */
    constructor(address admin) {
        _grantRole(ADMIN, admin);
        _grantRole(COMPANY, admin);
        _grantRole(GOVERNMENT, admin);
    }

    /**
     * @notice Creates a new license and assigns it to the caller.
     * @dev Only the COMPANY role can create new licenses.
     * @param licenseId The unique identifier of the license.
     */
    function createLicense(string memory licenseId) public nonReentrant {
        require(hasRole(COMPANY, _msgSender()), "Caller is not a COMPANY");
        require(licenses[licenseId] == address(0), "License already exists");

        licenses[licenseId] = _msgSender();
        licenseHolders[_msgSender()].push(licenseId);

        emit LicenseCreated(licenseId, _msgSender());
    }

    /**
     * @notice Assigns an existing license to a government entity.
     * @dev Only COMPANY or GOVERNMENT roles can assign licenses.
     * @param licenseId The unique identifier of the license.
     * @param assignee The address of the government entity.
     */
    function assignLicense(string memory licenseId, address assignee) public nonReentrant {
        require(
            hasRole(COMPANY, _msgSender()) || hasRole(GOVERNMENT, _msgSender()),
            "Caller does not have COMPANY or GOVERNMENT role"
        );
        require(licenses[licenseId] != address(0), "License does not exist");
        require(assignee != address(0), "Invalid assignee address");

        licenses[licenseId] = assignee;
        licenseHolders[assignee].push(licenseId);
        licenseHolders[licenses[licenseId]].push(licenseId); // Previous holder keeps the license

        emit LicenseAssigned(licenseId, _msgSender(), assignee);
    }

    /**
     * @notice Transfers a license from one address to another.
     * @dev Only the current holder of the license can transfer it.
     * @param licenseId The unique identifier of the license.
     * @param receiver The address to transfer the license to.
     */
    function transferLicense(string memory licenseId, address receiver) public nonReentrant {
        require(licenses[licenseId] == _msgSender(), "Caller is not the license holder");
        require(receiver != address(0), "Invalid receiver address");

        // Remove license from current holder
        string[] memory currentHolderLicenses = licenseHolders[_msgSender()];
        uint256 index = _findLicenseIndex(currentHolderLicenses, licenseId);
        _removeLicense(currentHolderLicenses, index);

        // Add license to receiver
        licenseHolders[receiver].push(licenseId);
        licenses[licenseId] = receiver;

        emit LicenseTransferred(licenseId, _msgSender(), receiver);
    }

    /**
     * @notice Revokes a license and removes it from circulation.
     * @dev Only COMPANY or GOVERNMENT roles can revoke a license.
     * @param licenseId The unique identifier of the license.
     */
    function revokeLicense(string memory licenseId) public nonReentrant {
        require(
            hasRole(COMPANY, _msgSender()) || hasRole(GOVERNMENT, _msgSender()),
            "Caller does not have COMPANY or GOVERNMENT role"
        );
        require(licenses[licenseId] != address(0), "License does not exist");

        // Remove license from current holder
        string[] memory currentHolderLicenses = licenseHolders[licenses[licenseId]];
        uint256 index = _findLicenseIndex(currentHolderLicenses, licenseId);
        _removeLicense(currentHolderLicenses, index);

        // Set license holder to zero address
        licenses[licenseId] = address(0);

        emit LicenseRevoked(licenseId, _msgSender());
    }

    /**
     * @notice Finds the index of a license in an array of licenses.
     * @dev Internal function to help manage license arrays.
     * @param licensesArray The array of licenses.
     * @param licenseId The ID of the license to find.
     * @return The index of the license in the array.
     */
    function _findLicenseIndex(string[] memory licensesArray, string memory licenseId)
        internal
        pure
        returns (uint256)
    {
        uint256 index = 0;
        for (index; index < licensesArray.length; index++) {
            if (keccak256(bytes(licensesArray[index])) == keccak256(bytes(licenseId))) {
                break;
            }
        }
        require(index < licensesArray.length, "License not found in array");
        return index;
    }

    /**
     * @notice Removes a license from an array at a specific index.
     * @dev Internal function to help manage license arrays.
     * @param licensesArray The array of licenses.
     * @param index The index of the license to remove.
     */
    function _removeLicense(string[] storage licensesArray, uint256 index) internal {
        // Overwrite the element at index with the last element
        if (index < licensesArray.length - 1) {
            licensesArray[index] = licensesArray[licensesArray.length - 1];
        }
        // Remove the last element
        licensesArray.pop();
    }
}
